import java.util.*;

public class Ex08GenericEqualsHashCode {
    static class BadKey {
        int id;
        BadKey(int id) { this.id = id; }
        @Override public boolean equals(Object o) { return o instanceof BadKey b && b.id == id; }
    }
    static class GoodKey {
        int id;
        GoodKey(int id) { this.id = id; }
        @Override public boolean equals(Object o) { return o instanceof GoodKey g && g.id == id; }
        @Override public int hashCode() { return id; }
    }
    public static void main(String[] args) {
        Map<BadKey, String> bad = new HashMap<>();
        bad.put(new BadKey(1), "x");
        Map<GoodKey, String> good = new HashMap<>();
        good.put(new GoodKey(1), "x");
        System.out.println("bad get(new BadKey(1))=" + bad.get(new BadKey(1)));
        System.out.println("good get(new GoodKey(1))=" + good.get(new GoodKey(1)));
    }
}
